558	        assert!(g
559	            .iter()
560	            .any(|r| r.matches("Write", &json!({ "path": ".git/config", "content": "x" }))));
561	        assert!(g
562	            .iter()
563	            .any(|r| r.matches("Edit", &json!({ "path": "a/.ssh/known_hosts" }))));
564	        assert!(g
565	            .iter()
566	            .any(|r| r.matches("Write", &json!({ "path": ".env.local", "content": "x" }))));
