594	        assert!(dr.matches("Read", &json!({ "path": "config/.env" })));
595	        assert!(!dr.matches("Read", &json!({ "path": "config/app.toml" })));
596	        assert!(!dr.matches("Edit", &json!({ "path": ".env" }))); // read-scoped
597	
598	        let de = DenyRule::edit("src/**");
599	        assert!(de.matches("Edit", &json!({ "path": "src/a.rs" })));
600	        assert!(de.matches("Write", &json!({ "path": "src/a.rs" }))); // edit covers Write
601	        assert!(!de.matches("Read", &json!({ "path": "src/a.rs" })));
602	    }
603	
604	    #[test]
605	    fn allow_rule_tool_and_path() {
606	        assert!(AllowRule::tool("WebSearch").matches("WebSearch", &json!({})));
607	        assert!(!AllowRule::tool("WebSearch").matches("Bash", &json!({})));
608	
609	        assert!(AllowRule::read("src/**").matches("Read", &json!({ "path": "src/a.rs" })));
610	        assert!(AllowRule::edit("src/**").matches("Write", &json!({ "path": "src/a.rs" })));
611	        assert!(!AllowRule::edit("src/**").matches("Write", &json!({ "path": "etc/x" })));
612	        // read is scoped to Read — it does NOT cover Write/Edit
613	        assert!(!AllowRule::read("src/**").matches("Write", &json!({ "path": "src/a.rs" })));
614	        // a missing/non-string path arg matches nothing (no panic)
615	        assert!(!AllowRule::read("**").matches("Read", &json!({})));
616	        assert!(!DenyRule::read("**").matches("Read", &json!({})));
617	    }
618	
619	    #[test]
620	    fn allow_rule_bash_command_requires_every_subcommand() {
621	        let rule = AllowRule::bash_command("git");
622	        assert!(rule.matches("Bash", &json!({ "command": "git status && git push" })));
623	        // a non-git sub-command means the allow rule does NOT fire (fail-closed)
624	        assert!(!rule.matches("Bash", &json!({ "command": "git status && rm -rf ." })));
625	        assert!(!rule.matches("Bash", &json!({ "command": "" })));
626	        assert!(!rule.matches("Other", &json!({ "command": "git status" })));
627	    }
628	
629	    #[test]
630	    fn deny_rule_matches_exact_tool_name_only() {
631	        let rule = DenyRule::tool("rm");
632	        assert!(rule.matches("rm", &json!({})));
633	        assert!(!rule.matches("ls", &json!({})));
634	        assert!(rule.matches("rm", &json!({"path": "/etc/passwd"})));
635	    }
636	
637	    #[test]
638	    fn bash_command_matches_any_subcommand_program() {
639	        let rule = DenyRule::bash_command("rm");
640	        let args = json!({ "command": "echo ok && rm -rf ." });
641	        assert!(rule.matches("Bash", &args));
642	        let safe = json!({ "command": "echo ok && ls" });
643	        assert!(!rule.matches("Bash", &safe));
644	    }
645	
646	    #[test]
647	    fn bash_command_is_tool_scoped() {
648	        let rule = DenyRule::bash_command("rm");
649	        // A non-Bash tool carrying a `command` field must not trip it.
650	        assert!(!rule.matches("Other", &json!({ "command": "rm -rf ." })));
651	    }
652	
653	    #[test]
654	    fn bash_command_sees_through_sudo_and_bash_c() {
655	        let rule = DenyRule::bash_command("rm");
656	        assert!(rule.matches("Bash", &json!({ "command": "sudo rm -rf /" })));
657	        assert!(rule.matches("Bash", &json!({ "command": "bash -c 'rm -rf /'" })));
658	    }
