521	async fn run_tools_concurrent<Ctx>(
522	    tools: &[std::sync::Arc<dyn crate::Tool<Ctx>>],
523	    calls: &[crate::ToolCallRequest],
524	    interceptors: &crate::control::Interceptors<'_, Ctx>,
525	    tool_ctx: &crate::ToolContext<Ctx>,
526	    limit: Option<std::num::NonZeroUsize>,
527	    parent: &tracing::Span,
528	) -> (Vec<crate::ToolCallOutcome>, Vec<crate::AgentEvent>)
529	where
530	    Ctx: Send + Sync + 'static,
531	{
532	    let denied_events: std::sync::Mutex<Vec<crate::AgentEvent>> = std::sync::Mutex::new(Vec::new());
533	    let redact_output = interceptors.ctx.redact_output();
534	    let secrets = crate::redaction::SecretSet::from_env_and_extra(interceptors.ctx.extra_secrets());
535	
536	    let futures = calls.iter().map(|call| {
537	        let tool = tools.iter().find(|t| t.name() == call.name).cloned();
538	        let effect = tool
539	            .as_ref()
540	            .map(|t| t.effect())
541	            .unwrap_or(crate::ToolEffect::SideEffect);
542	        let call_id = call.call_id.clone();
543	        let name = call.name.clone();
544	        let orig_args = call.args.clone();
545	        let denied_events = &denied_events;
546	        let secrets = &secrets;
547	        let span = tracing::info_span!(
548	            target: "paigasus::core::agent",
549	            parent: parent,
550	            "tool.execute",
551	            otel.name = tracing::field::Empty,
552	            otel.kind = "internal",
553	            gen_ai.operation.name = "execute_tool",
554	            gen_ai.tool.name = %name,
555	            otel.status_code = tracing::field::Empty,
556	        );
557	        span.record("otel.name", format!("execute_tool {name}").as_str());
558	        async move {
559	            // PreToolUse hook.
560	            let pre = interceptors
561	                .fire(&crate::HookEvent::PreToolUse {
562	                    tool: name.clone(),
563	                    args: orig_args.clone(),
564	                })
565	                .await;
566	            if let Some(reason) = pre.denied {
567	                return crate::ToolCallOutcome {
568	                    call_id,
569	                    result: Err(format!("blocked by PreToolUse hook: {reason}")),
570	                };
571	            }
572	            let mut args = pre.replacement.unwrap_or(orig_args);
573	
574	            // Permission authorize on the effective args. `Interceptors::authorize`
575	            // delegates to `RunContext::authorize_tool` — the same primitive a
576	            // durable runner calls directly via `execute_tool_call`.
577	            match interceptors.authorize(&name, effect, &args).await {
578	                crate::PermissionDecision::Allow => {}
579	                crate::PermissionDecision::Replace { args: sanitized } => {
580	                    args = sanitized;
581	                }
582	                crate::PermissionDecision::Deny { reason }
583	                | crate::PermissionDecision::AskUser { prompt: reason } => {
584	                    denied_events
585	                        .lock()
586	                        .unwrap()
587	                        .push(crate::AgentEvent::PermissionDenied {
588	                            tool: name.clone(),
589	                            reason: reason.clone(),
590	                        });
591	                    return crate::ToolCallOutcome {
592	                        call_id,
593	                        result: Err(format!("permission denied: {reason}")),
594	                    };
595	                }
596	            }
597	
598	            // Invoke. Keep the tool's raw JSON output so the PostToolUse hook
599	            // sees the structured value, not a stringified form.
600	            let outcome = match tool {
601	                Some(t) => match t.invoke(tool_ctx, args).await {
602	                    Ok(output) => Ok(output.content),
603	                    Err(e) => {
604	                        tracing::Span::current().record("otel.status_code", "ERROR");
605	                        Err(e.to_string())
606	                    }
607	                },
608	                None => {
609	                    tracing::Span::current().record("otel.status_code", "ERROR");
610	                    Err(format!("unknown tool: {name}"))
611	                }
612	            };
613	
614	            // PostToolUse hook (ReplaceOutput / Deny→denial). The hook receives
615	            // the raw `serde_json::Value`; a `ReplaceOutput` value (or the
616	            // original) is rendered to content parts only at the end.
617	            let outcome = match outcome {
618	                Ok(output_json) => {
619	                    let post = interceptors
620	                        .fire(&crate::HookEvent::PostToolUse {
621	                            tool: name.clone(),
622	                            output: output_json.clone(),
623	                        })
624	                        .await;
625	                    if let Some(reason) = post.denied {
626	                        Err(format!("blocked by PostToolUse hook: {reason}"))
627	                    } else {
628	                        let final_json = post.replacement.unwrap_or(output_json);
629	                        // Redaction is the FINAL transform — after user PostToolUse
630	                        // hooks — so a hook cannot reintroduce an unredacted secret.
631	                        // Shared with the durable-runner pipeline in `tool_exec.rs`.
632	                        Ok(crate::finalize_tool_output(
633	                            final_json,
634	                            redact_output,
635	                            secrets,
636	                        ))
637	                    }
638	                }
639	                Err(e) => Err(e),
640	            };
641	
642	            crate::ToolCallOutcome {
643	                call_id,
644	                result: outcome,
645	            }
646	        }
647	        .instrument(span)
648	    });
649	
650	    let outcomes = match limit {
651	        None => futures_util::future::join_all(futures).await,
652	        Some(n) => {
653	            use futures_util::stream::StreamExt as _;
654	            let collected: Vec<_> = futures.collect();
655	            futures_util::stream::iter(collected)
656	                .buffered(n.get())
657	                .collect()
658	                .await
659	        }
660	    };
661	    (outcomes, denied_events.into_inner().unwrap())
662	}
