1240	/// Out-of-band carrier for a run's terminal structured [`AgentError`].
1241	///
1242	/// The [`crate::AgentEvent`] stream stays string-based
1243	/// ([`crate::AgentEvent::RunFailed`]` { error: String }`) so it remains `Clone`
1244	/// and snapshot-stable; the structured error rides this side-channel instead.
1245	/// One slot lives on each [`RunContext`]; the agent records into it at the
1246	/// moment of failure and a [`crate::Runner`] (or
1247	/// [`crate::RunResultStreaming::collect`]) reads it **after the event stream is
1248	/// fully drained** — see [`crate::RunResultStreaming::collect`] for why the
1249	/// read must come after draining.
1250	#[derive(Clone, Default, Debug)]
1251	pub struct FailureSlot(Arc<Mutex<Option<AgentError>>>);
1252	
1253	impl FailureSlot {
1254	    /// Create an empty slot.
1255	    pub fn new() -> Self {
1256	        Self::default()
1257	    }
1258	
1259	    /// Record the terminal structured error. Called once per run, at any point
1260	    /// before the stream terminates; last write wins.
1261	    pub fn set(&self, err: AgentError) {
1262	        *self.0.lock().unwrap_or_else(|e| e.into_inner()) = Some(err);
1263	    }
1264	
1265	    /// Take the recorded error, if any. Read once at the boundary, after the
1266	    /// event stream has been fully drained.
1267	    pub fn take(&self) -> Option<AgentError> {
1268	        self.0.lock().unwrap_or_else(|e| e.into_inner()).take()
1269	    }
1270	}
