1272	// A non-`Send`/`Sync` payload added to `AgentError` would silently break the
1273	// agent's `BoxStream<'static, AgentEvent>: Send` bound far downstream. Fail here
1274	// instead, with a clear pointer to the cause.
1275	const _: fn() = || {
1276	    fn assert_send_sync<T: Send + Sync>() {}
1277	    assert_send_sync::<FailureSlot>();
1278	};
