1	//! Explicit state machine for the agent loop.
2	//!
3	//! Per ADR *"Explicit `LoopState` enum, not a callback maze"*, the
4	//! state machine is data: a pure [`transition`] function takes the
5	//! current state plus the most recent input and returns the next
6	//! state, the events to emit, and the side effect to perform. Durable
7	//! runners (Temporal, AgentCore in later tickets) reuse the same
8	//! function with their own driver.
9	
10	use crate::{
11	    AgentError, AgentEvent, ContentPart, FinishReason, Item, ModelRequest, ModelSettings,
12	    ResponseFormat, TokenUsage, ToolDef,
13	};
14	
15	/// The explicit, observable state of the agent loop.
16	///
17	/// One variant per high-level phase. Does **not** derive `Clone`:
18	/// `Failed(AgentError)` wraps `anyhow::Error` (not `Clone`). The
19	/// transition function takes input and returns outcome by value; tests
20	/// use `assert_matches!` on `next_state` instead of equality.
21	#[derive(Debug)]
22	#[non_exhaustive]
23	pub enum LoopState {
24	    /// About to call the model for turn `turn`.
25	    CallingModel {
26	        /// Zero-indexed turn counter.
27	        turn: u32,
28	        /// Cumulative token usage of all model turns completed before turn
29	        /// `turn` (SMA-402); `default()` at turn 0. Folded forward on every
30	        /// transition; the terminal `Done` / `RunCompleted` carry the grand total.
31	        usage: TokenUsage,
32	    },
33	    /// The model produced tool calls; about to execute them. `turn` is
34	    /// the turn that produced the calls — the next [`LoopState::CallingModel`]
35	    /// state will be `turn + 1`.
36	    ExecutingTools {
37	        /// The tool calls to execute concurrently.
38	        calls: Vec<ToolCallRequest>,
39	        /// The turn that produced these calls.
40	        turn: u32,
41	        /// Cumulative token usage of all model turns completed so far —
42	        /// including the turn that produced these calls (SMA-402). Carried
43	        /// forward unchanged across tool execution (tools add no tokens).
44	        usage: TokenUsage,
45	    },
46	    /// Handing off to another agent; carries the threaded transcript and the
47	    /// cumulative usage of all turns completed before the handoff (SMA-324).
48	    ApplyingHandoff {
49	        /// Name of the target agent.
50	        target: String,
51	        /// Conversation transcript to hand off.
52	        transcript: Vec<Item>,
53	        /// Cumulative usage of turns completed before the handoff.
54	        usage: TokenUsage,
55	    },
56	    /// Compacting session history. **Not driveable in SMA-314.**
57	    Compacting,
58	    /// Awaiting approval for a sensitive tool call.
59	    /// **Not driveable in SMA-314.**
60	    NeedsApproval {
61	        /// The tool calls awaiting approval.
62	        pending: Vec<ToolCallRequest>,
63	    },
64	    /// Constrained finalizing turn: the model is asked to emit the
65	    /// structured output for the configured `output_type`.
66	    Finalizing {
67	        /// The turn index that produced this finalizing request.
68	        turn: u32,
69	        /// Cumulative token usage of all model turns completed so far,
70	        /// including the turn that triggered finalizing (SMA-402).
71	        usage: TokenUsage,
72	    },
73	    /// The one allowed repair turn after a failed finalizing validation.
74	    RepairingOutput {
75	        /// The turn index of the finalizing turn being repaired.
76	        turn: u32,
77	        /// Cumulative token usage of all model turns completed so far,
78	        /// including the failed finalizing turn (SMA-402).
79	        usage: TokenUsage,
80	    },
81	    /// Terminal: run completed successfully.
82	    Done(FinalOutput),
83	    /// Terminal: run failed.
84	    Failed(AgentError),
85	}
86	
87	/// One tool call the model has requested. Pure data.
88	#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
89	pub struct ToolCallRequest {
90	    /// The provider-assigned call id (echoed back in `Item::ToolResult`).
91	    pub call_id: String,
92	    /// Tool name (matches [`crate::Tool::name`]).
93	    pub name: String,
94	    /// JSON-encoded arguments object.
95	    pub args: serde_json::Value,
96	}
97	
98	/// Outcome of one tool execution. Errors are stringified so the
99	/// outcome implements `Clone` — `ToolError` carries `anyhow::Error`,
100	/// which is not `Clone`.
101	#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
102	pub struct ToolCallOutcome {
103	    /// The call id this outcome corresponds to.
104	    pub call_id: String,
105	    /// Either the tool's content output or a stringified error.
106	    pub result: Result<Vec<ContentPart>, String>,
107	}
108	
109	/// Final assistant content + aggregated token usage at termination.
110	#[derive(Debug, Clone, Default)]
111	#[non_exhaustive]
112	pub struct FinalOutput {
113	    /// The terminal assistant content.
114	    pub content: Vec<ContentPart>,
115	    /// Aggregated token usage across all turns.
116	    pub usage: TokenUsage,
117	}
118	
119	impl FinalOutput {
120	    /// Concatenate all `ContentPart::Text` parts. This is the
121	    /// canonical rendering that feeds `RunResult.final_output` when
122	    /// `T = String`.
123	    pub fn as_text(&self) -> String {
124	        self.content
125	            .iter()
126	            .filter_map(|p| match p {
127	                ContentPart::Text { text } => Some(text.as_str()),
128	                _ => None,
129	            })
130	            .collect::<Vec<_>>()
131	            .join("")
132	    }
133	}
134	
135	/// Data fed *into* the next [`transition`] call.
136	#[derive(Debug, Clone)]
137	#[non_exhaustive]
138	pub enum TransitionInput {
139	    /// Seeds the loop with the initial conversation.
140	    Start {
141	        /// The user's input messages.
142	        messages: Vec<Item>,
143	    },
144	    /// One model turn aggregated.
145	    ModelResponse {
146	        /// Items produced this turn (assistant message + tool calls).
147	        items: Vec<Item>,
148	        /// Token usage for this turn.
149	        usage: TokenUsage,
150	        /// Why the model stopped emitting tokens.
151	        finish_reason: FinishReason,
152	    },
153	    /// All tool calls for one turn have completed.
154	    ToolResults {
155	        /// Per-call outcomes.
156	        outcomes: Vec<ToolCallOutcome>,
157	    },
158	}
159	
160	/// Side effect the async driver must run before the next transition.
161	#[derive(Debug, Clone)]
162	#[non_exhaustive]
163	pub enum NextAction {
164	    /// Call the model with this request; produce a `ModelResponse`.
165	    CallModel {
166	        /// The request to send.
167	        request: ModelRequest,
168	    },
169	    /// Execute these tool calls concurrently; produce a `ToolResults`.
170	    ExecuteTools {
171	        /// The calls to fan out.
172	        calls: Vec<ToolCallRequest>,
173	    },
174	    /// The current state is terminal; stop driving.
175	    Terminate,
176	    /// Delegate to a handoff target. The driver reads the target, transcript,
177	    /// and pre-handoff usage from the [`LoopState::ApplyingHandoff`] state.
178	    Handoff,
179	}
180	
181	/// What [`transition`] needs to know about the agent and config for
182	/// one step. Doesn't carry user `Ctx` — that's the driver's concern.
183	pub struct TransitionCtx<'a> {
184	    /// Tool definitions available this run.
185	    pub tools: &'a [ToolDef],
186	    /// Provider-tuning knobs.
187	    pub model_settings: &'a ModelSettings,
188	    /// Maximum number of turns before the loop fails.
189	    pub max_turns: u32,
190	    /// The driver's accumulated conversation so far. The driver
191	    /// appends incoming items before calling [`transition`] and passes
192	    /// the slice in — [`transition`] reads but never mutates.
193	    pub conversation: &'a [Item],
194	    /// Structured-output type, when the agent configured one. Drives the
195	    /// constrained finalizing turn and output validation.
196	    pub output: Option<&'a crate::OutputType>,
197	    /// Synthetic transfer-tool descriptors, one per handoff candidate. Empty
198	    /// when the agent has no handoffs.
199	    pub handoffs: &'a [crate::HandoffDef],
200	}
201	
202	/// One transition step's result. Not `Clone` (carries `LoopState`).
203	#[derive(Debug)]
204	pub struct TransitionOutcome {
205	    /// The state after this step.
206	    pub next_state: LoopState,
207	    /// Events to yield through the driver's event stream.
208	    pub events: Vec<AgentEvent>,
209	    /// Side effect the driver must run before the next step.
210	    pub next_action: NextAction,
211	    /// Items the driver must append to its owned conversation before the
212	    /// next step (e.g. a synthesized repair message). Empty in most arms.
213	    pub conversation_appends: Vec<Item>,
214	}
215	
216	/// Pure state-machine step. **No async, no tokio, no IO.**
217	///
218	/// Given the current state and the most recent input, produce the
219	/// next state, the events to emit, and the side effect to perform.
220	/// Resumable by construction: a durable runner can persist
221	/// [`LoopState`] plus the accumulated conversation and rehydrate the
222	/// loop at any transition boundary.
223	pub fn transition(
224	    state: &LoopState,
225	    input: TransitionInput,
226	    ctx: &TransitionCtx<'_>,
227	) -> TransitionOutcome {
228	    match (state, input) {
229	        // Max turns reached at the CallingModel boundary → fail fast.
230	        (LoopState::CallingModel { turn, .. }, _) if *turn >= ctx.max_turns => TransitionOutcome {
231	            next_state: LoopState::Failed(AgentError::MaxTurnsExceeded(ctx.max_turns)),
232	            events: vec![AgentEvent::RunFailed {
233	                error: format!("max turns ({}) exceeded", ctx.max_turns),
234	            }],
235	            next_action: NextAction::Terminate,
236	            conversation_appends: Vec::new(),
237	        },
238	        // Start seeds the loop: emit TurnStarted, request CallModel.
239	        (LoopState::CallingModel { turn, usage: prior }, TransitionInput::Start { .. })
240	            if *turn < ctx.max_turns =>
241	        {
242	            match ctx.output {
243	                Some(out) if ctx.tools.is_empty() => {
244	                    let request = ModelRequest {
245	                        messages: ctx.conversation.to_vec(),
246	                        tools: Vec::new(),
247	                        model_settings: constrained_settings(ctx.model_settings, out),
248	                    };
249	                    TransitionOutcome {
250	                        next_state: LoopState::Finalizing {
251	                            turn: *turn,
252	                            usage: *prior,
253	                        },
254	                        events: vec![AgentEvent::TurnStarted { turn: *turn }],
255	                        next_action: NextAction::CallModel { request },
256	                        conversation_appends: Vec::new(),
257	                    }
258	                }
259	                _ => {
260	                    let request = ModelRequest {
261	                        messages: ctx.conversation.to_vec(),
262	                        tools: turn_tools(ctx),
263	                        model_settings: ctx.model_settings.clone(),
264	                    };
265	                    TransitionOutcome {
266	                        next_state: LoopState::CallingModel {
267	                            turn: *turn,
268	                            usage: *prior,
269	                        },
270	                        events: vec![AgentEvent::TurnStarted { turn: *turn }],
271	                        next_action: NextAction::CallModel { request },
272	                        conversation_appends: Vec::new(),
273	                    }
274	                }
275	            }
276	        }
277	        // Model produced tool calls → fan out to ExecutingTools.
278	        (
279	            LoopState::CallingModel { turn, usage: prior },
280	            TransitionInput::ModelResponse { items, usage, .. },
281	        ) if items.iter().any(|i| matches!(i, Item::ToolCall { .. })) => {
282	            // Handoff takes precedence over regular tool calls (first wins).
283	            if let Some(target) = items.iter().find_map(|i| match i {
284	                Item::ToolCall { name, .. } => ctx
285	                    .handoffs
286	                    .iter()
287	                    .find(|h| &h.tool_name == name)
288	                    .map(|h| h.target.clone()),
289	                _ => None,
290	            }) {
291	                let total = accumulate(*prior, usage);
292	                let mut events: Vec<AgentEvent> = Vec::new();
293	                for item in &items {
294	                    match item {
295	                        Item::AssistantMessage { .. } => {
296	                            events.push(AgentEvent::MessageOutput { item: item.clone() });
297	                        }
298	                        Item::ToolCall { name, .. }
299	                            if ctx.handoffs.iter().any(|h| &h.tool_name == name) =>
300	                        {
301	                            events.push(AgentEvent::ToolCallItem { item: item.clone() });
302	                        }
303	                        _ => {}
304	                    }
305	                }
306	                return TransitionOutcome {
307	                    next_state: LoopState::ApplyingHandoff {
308	                        target,
309	                        transcript: thread_handoff_transcript(ctx.conversation),
310	                        usage: total,
311	                    },
312	                    events,
313	                    next_action: NextAction::Handoff,
314	                    conversation_appends: Vec::new(),
315	                };
316	            }
317	            // (existing ExecutingTools logic continues unchanged below)
318	            let mut events: Vec<AgentEvent> = Vec::new();
319	            let mut calls: Vec<ToolCallRequest> = Vec::new();
320	            for item in &items {
321	                match item {
322	                    Item::AssistantMessage { .. } => {
323	                        events.push(AgentEvent::MessageOutput { item: item.clone() });
324	                    }
325	                    Item::ToolCall {
326	                        call_id,
327	                        name,
328	                        args,
329	                    } => {
330	                        events.push(AgentEvent::ToolCallItem { item: item.clone() });
331	                        calls.push(ToolCallRequest {
332	                            call_id: call_id.clone(),
333	                            name: name.clone(),
334	                            args: args.clone(),
335	                        });
336	                    }
337	                    _ => {}
338	                }
339	            }
340	            TransitionOutcome {
341	                next_state: LoopState::ExecutingTools {
342	                    calls: calls.clone(),
343	                    turn: *turn,
344	                    usage: accumulate(*prior, usage),
345	                },
346	                events,
347	                next_action: NextAction::ExecuteTools { calls },
348	                conversation_appends: Vec::new(),
349	            }
350	        }
351	        // Model produced a response with no tool calls → either issue a
352	        // constrained finalizing turn (output set) or terminate (no output).
353	        (
354	            LoopState::CallingModel { turn, usage: prior },
355	            TransitionInput::ModelResponse { items, usage, .. },
356	        ) if !items.iter().any(|i| matches!(i, Item::ToolCall { .. })) => {
357	            let total = accumulate(*prior, usage);
358	            let mut events: Vec<AgentEvent> = items
359	                .iter()
360	                .filter(|i| matches!(i, Item::AssistantMessage { .. }))
361	                .cloned()
362	                .map(|item| AgentEvent::MessageOutput { item })
363	                .collect();
364	
365	            match ctx.output {
366	                Some(out) => {
367	                    // Phase 2: issue one constrained finalizing turn (real tools
368	                    // withdrawn; the prior unconstrained answer stays in context).
369	                    // The finalizing call is a distinct model invocation, so it
370	                    // gets its own turn number (the unconstrained turn already
371	                    // emitted `TurnStarted { turn }`).
372	                    let finalizing_turn = *turn + 1;
373	                    let request = ModelRequest {
374	                        messages: ctx.conversation.to_vec(),
375	                        tools: Vec::new(),
376	                        model_settings: constrained_settings(ctx.model_settings, out),
377	                    };
378	                    events.push(AgentEvent::TurnStarted {
379	                        turn: finalizing_turn,
380	                    });
381	                    TransitionOutcome {
382	                        next_state: LoopState::Finalizing {
383	                            turn: finalizing_turn,
384	                            usage: total,
385	                        },
386	                        events,
387	                        next_action: NextAction::CallModel { request },
388	                        conversation_appends: Vec::new(),
389	                    }
390	                }
391	                None => {
392	                    let content = last_assistant_content(&items);
393	                    events.push(AgentEvent::RunCompleted { usage: total });
394	                    TransitionOutcome {
395	                        next_state: LoopState::Done(FinalOutput {
396	                            content,
397	                            usage: total,
398	                        }),
399	                        events,
400	                        next_action: NextAction::Terminate,
401	                        conversation_appends: Vec::new(),
402	                    }
403	                }
404	            }
405	        }
406	        // Tool results complete → bump turn and ask the model again.
407	        (
408	            LoopState::ExecutingTools {
409	                turn, usage: prior, ..
410	            },
411	            TransitionInput::ToolResults { outcomes },
412	        ) => {
413	            let next_turn = turn + 1;
414	            let mut events: Vec<AgentEvent> = outcomes
415	                .into_iter()
416	                .map(|o| AgentEvent::ToolOutputItem {
417	                    item: Item::ToolResult {
418	                        call_id: o.call_id,
419	                        content: o
420	                            .result
421	                            .unwrap_or_else(|e| vec![ContentPart::Text { text: e }]),
422	                    },
423	                })
424	                .collect();
425	            if next_turn >= ctx.max_turns {
426	                events.push(AgentEvent::RunFailed {
427	                    error: format!("max turns ({}) exceeded", ctx.max_turns),
428	                });
429	                return TransitionOutcome {
430	                    next_state: LoopState::Failed(AgentError::MaxTurnsExceeded(ctx.max_turns)),
431	                    events,
432	                    next_action: NextAction::Terminate,
433	                    conversation_appends: Vec::new(),
434	                };
435	            }
436	            events.push(AgentEvent::TurnStarted { turn: next_turn });
437	            let request = ModelRequest {
438	                messages: ctx.conversation.to_vec(),
439	                tools: turn_tools(ctx),
440	                model_settings: ctx.model_settings.clone(),
441	            };
442	            TransitionOutcome {
443	                next_state: LoopState::CallingModel {
444	                    turn: next_turn,
445	                    usage: *prior,
446	                },
447	                events,
448	                next_action: NextAction::CallModel { request },
449	                conversation_appends: Vec::new(),
450	            }
451	        }
452	        // Finalizing: validate the model's structured output.
453	        (
454	            LoopState::Finalizing { turn, usage: prior },
455	            TransitionInput::ModelResponse { items, usage, .. },
456	        ) => {
457	            let Some(out) = ctx.output else {
458	                return TransitionOutcome {
459	                    next_state: LoopState::Failed(AgentError::Other(anyhow::anyhow!(
460	                        "Finalizing state without output type"
461	                    ))),
462	                    events: vec![AgentEvent::RunFailed {
463	                        error: "internal: Finalizing without output type".to_owned(),
464	                    }],
465	                    next_action: NextAction::Terminate,
466	                    conversation_appends: Vec::new(),
467	                };
468	            };
469	            let total = accumulate(*prior, usage);
470	            let mut events: Vec<AgentEvent> = items
471	                .iter()
472	                .filter(|i| matches!(i, Item::AssistantMessage { .. }))
473	                .cloned()
474	                .map(|item| AgentEvent::MessageOutput { item })
475	                .collect();
476	            let content = last_assistant_content(&items);
477	            let has_tool_call = items.iter().any(|i| matches!(i, Item::ToolCall { .. }));
478	
479	            let validation = if has_tool_call {
480	                Err(vec![
481	                    "model called a tool on the constrained finalizing turn".to_owned(),
482	                ])
483	            } else {
484	                validate_terminal(out, &content)
485	            };
486	
487	            match validation {
488	                Ok(()) => {
489	                    events.push(AgentEvent::RunCompleted { usage: total });
490	                    TransitionOutcome {
491	                        next_state: LoopState::Done(FinalOutput {
492	                            content,
493	                            usage: total,
494	                        }),
495	                        events,
496	                        next_action: NextAction::Terminate,
497	                        conversation_appends: Vec::new(),
498	                    }
499	                }
500	                Err(schema_errors) => {
501	                    let msg = repair_message(&out.name, &schema_errors);
502	                    let mut messages = ctx.conversation.to_vec();
503	                    messages.push(msg.clone());
504	                    let request = ModelRequest {
505	                        messages,
506	                        tools: Vec::new(),
507	                        model_settings: constrained_settings(ctx.model_settings, out),
508	                    };
509	                    events.push(AgentEvent::RepairStarted { attempt: 1 });
510	                    TransitionOutcome {
511	                        next_state: LoopState::RepairingOutput {
512	                            turn: *turn,
513	                            usage: total,
514	                        },
515	                        events,
516	                        next_action: NextAction::CallModel { request },
517	                        conversation_appends: vec![msg],
518	                    }
519	                }
520	            }
521	        }
522	        // RepairingOutput: one allowed repair turn — success → Done, failure → Failed.
523	        (
524	            LoopState::RepairingOutput { usage: prior, .. },
525	            TransitionInput::ModelResponse { items, usage, .. },
526	        ) => {
527	            let Some(out) = ctx.output else {
528	                return TransitionOutcome {
529	                    next_state: LoopState::Failed(AgentError::Other(anyhow::anyhow!(
530	                        "RepairingOutput state without output type"
531	                    ))),
532	                    events: vec![AgentEvent::RunFailed {
533	                        error: "internal: RepairingOutput without output type".to_owned(),
534	                    }],
535	                    next_action: NextAction::Terminate,
536	                    conversation_appends: Vec::new(),
537	                };
538	            };
539	            let total = accumulate(*prior, usage);
540	            let mut events: Vec<AgentEvent> = items
541	                .iter()
542	                .filter(|i| matches!(i, Item::AssistantMessage { .. }))
543	                .cloned()
544	                .map(|item| AgentEvent::MessageOutput { item })
545	                .collect();
546	            let content = last_assistant_content(&items);
547	            let has_tool_call = items.iter().any(|i| matches!(i, Item::ToolCall { .. }));
548	
549	            let validation = if has_tool_call {
550	                Err(vec!["model called a tool on the repair turn".to_owned()])
551	            } else {
552	                validate_terminal(out, &content)
553	            };
554	
555	            match validation {
556	                Ok(()) => {
557	                    events.push(AgentEvent::RunCompleted { usage: total });
558	                    TransitionOutcome {
559	                        next_state: LoopState::Done(FinalOutput {
560	                            content,
561	                            usage: total,
562	                        }),
563	                        events,
564	                        next_action: NextAction::Terminate,
565	                        conversation_appends: Vec::new(),
566	                    }
567	                }
568	                Err(schema_errors) => {
569	                    let final_text = flatten_text(&content);
570	                    events.push(AgentEvent::StructuredOutputFailed {
571	                        schema_errors: schema_errors.clone(),
572	                        final_text: final_text.clone(),
573	                    });
574	                    events.push(AgentEvent::RunFailed {
575	                        error: "invalid structured output after one repair attempt".to_owned(),
576	                    });
577	                    TransitionOutcome {
578	                        next_state: LoopState::Failed(AgentError::InvalidStructuredOutput {
579	                            schema_errors,
580	                            final_text,
581	                        }),
582	                        events,
583	                        next_action: NextAction::Terminate,
584	                        conversation_appends: Vec::new(),
585	                    }
586	                }
587	            }
588	        }
589	        // Unreachable-in-SMA-314 variants surface NotImplemented and Terminate.
590	        (LoopState::Compacting, _) => not_implemented("compaction"),
591	        (LoopState::NeedsApproval { .. }, _) => not_implemented("approval"),
592	        // Other cases land in subsequent tasks.
593	        (s, i) => TransitionOutcome {
594	            next_state: LoopState::Failed(AgentError::Other(anyhow::anyhow!(
595	                "invalid transition: {s:?} ← {i:?}"
596	            ))),
597	            events: vec![AgentEvent::RunFailed {
598	                error: format!("invalid transition: {s:?} ← {i:?}"),
599	            }],
600	            next_action: NextAction::Terminate,
601	            conversation_appends: Vec::new(),
602	        },
603	    }
604	}
605	
606	/// Helper to surface `NotImplemented` for deferred-variant transitions.
607	fn not_implemented(feature: &'static str) -> TransitionOutcome {
608	    TransitionOutcome {
609	        next_state: LoopState::Failed(AgentError::NotImplemented { feature }),
610	        events: vec![AgentEvent::RunFailed {
611	            error: format!("not yet implemented: {feature}"),
612	        }],
613	        next_action: NextAction::Terminate,
614	        conversation_appends: Vec::new(),
615	    }
616	}
617	
618	/// Fold one turn's final usage into the running cross-turn total (SMA-402).
619	/// `TokenUsage` is `Copy`; returns the new cumulative total.
620	fn accumulate(prior: TokenUsage, this_turn: TokenUsage) -> TokenUsage {
621	    let mut total = prior;
622	    total.add(this_turn);
623	    total
624	}
625	
626	/// Build constrained model settings for a finalizing/repair turn: inject the
627	/// `output_type`-derived `response_format` (raw schema, strict mode) and clear
628	/// any caller tool_choice (Anthropic forces its own synthesized tool).
629	fn constrained_settings(base: &ModelSettings, output: &crate::OutputType) -> ModelSettings {
630	    let mut s = base.clone();
631	    s.response_format = Some(ResponseFormat::JsonSchema {
632	        name: output.name.clone(),
633	        schema: output.schema.as_value().clone(),
634	        strict: true,
635	    });
636	    s.tool_choice = None;
637	    s
638	}
639	
640	/// Concatenate `ContentPart::Text` parts (the structured output arrives as text
641	/// on both providers).
642	fn flatten_text(content: &[ContentPart]) -> String {
643	    content
644	        .iter()
645	        .filter_map(|p| match p {
646	            ContentPart::Text { text } => Some(text.as_str()),
647	            _ => None,
648	        })
649	        .collect::<Vec<_>>()
650	        .join("")
651	}
652	
653	/// Parse + validate terminal text against the output type.
654	/// `Ok(())` on success; `Err(schema_errors)` otherwise (non-JSON included).
655	fn validate_terminal(
656	    output: &crate::OutputType,
657	    content: &[ContentPart],
658	) -> Result<(), Vec<String>> {
659	    let text = flatten_text(content);
660	    let value: serde_json::Value = match serde_json::from_str(text.trim()) {
661	        Ok(v) => v,
662	        Err(e) => return Err(vec![format!("response was not valid JSON: {e}")]),
663	    };
664	    output.validate(&value)
665	}
666	
667	/// Synthesize the one repair instruction sent back to the model.
668	fn repair_message(name: &str, errors: &[String]) -> Item {
669	    let text = format!(
670	        "Your previous response did not match the required `{name}` schema. \
671	         Errors: {}. Reply with ONLY a JSON value matching the schema — \
672	         no prose, no code fences.",
673	        errors.join("; ")
674	    );
675	    Item::UserMessage {
676	        content: vec![ContentPart::Text { text }],
677	    }
678	}
679	
680	/// The last `AssistantMessage` content in a list of items.
681	fn last_assistant_content(items: &[Item]) -> Vec<ContentPart> {
682	    items
683	        .iter()
684	        .rev()
685	        .find_map(|i| match i {
686	            Item::AssistantMessage { content, .. } => Some(content.clone()),
687	            _ => None,
688	        })
689	        .unwrap_or_default()
690	}
691	
692	/// The synthetic `ToolDef` the model sees for one handoff (no arguments — the
693	/// conversation is the payload).
694	fn handoff_tool_def(def: &crate::HandoffDef) -> ToolDef {
695	    ToolDef {
696	        name: def.tool_name.clone(),
697	        description: def.description.clone(),
698	        schema: serde_json::json!({
699	            "type": "object",
700	            "properties": {},
701	            "additionalProperties": false
702	        }),
703	    }
704	}
705	
706	/// Real tools + synthetic transfer tools, for an unconstrained model turn.
707	fn turn_tools(ctx: &TransitionCtx<'_>) -> Vec<ToolDef> {
708	    let mut tools = ctx.tools.to_vec();
709	    tools.extend(ctx.handoffs.iter().map(handoff_tool_def));
710	    tools
711	}
712	
713	/// Thread the parent transcript for a handoff target: drop the leading
714	/// `System` and **all** tool calls/results (they reference tools the target
715	/// does not define), keep user + assistant-text items, and append a transfer
716	/// note so the target has routing context and the transcript is never empty.
717	fn thread_handoff_transcript(conversation: &[Item]) -> Vec<Item> {
718	    let mut out: Vec<Item> = conversation
719	        .iter()
720	        .filter(|i| {
721	            !matches!(
722	                i,
723	                Item::System { .. } | Item::ToolCall { .. } | Item::ToolResult { .. }
724	            )
725	        })
726	        .cloned()
727	        .collect();
728	    out.push(Item::UserMessage {
729	        content: vec![ContentPart::Text {
730	            text: "You are now handling a transferred conversation. \
731	                   Continue assisting the user."
732	                .to_owned(),
733	        }],
734	    });
735	    out
736	}
