1	//! The [`Session`] trait and its carrier types.
2	//!
3	//! `Session` models conversation persistence as an **append-only event
4	//! log**, not a flat message list. The event-log shape gives evals
5	//! (deterministic replay), durability (Temporal/Restate-style event
6	//! sourcing), and an audit trail for regulated deployments.
7	
8	use async_trait::async_trait;
9	use jiff::Timestamp;
10	use serde::{Deserialize, Serialize};
11	
12	use crate::{AgentEvent, ContentPart, Item};
13	
14	/// Conversation persistence as an append-only event log.
15	///
16	/// See the *Sessions* concept page for the rationale.
17	///
18	/// # Example
19	///
20	/// ```
21	/// use async_trait::async_trait;
22	/// use paigasus_helikon_core::{
23	///     ConversationSnapshot, SequenceId, Session, SessionError, SessionEvent,
24	/// };
25	///
26	/// struct MemorySession;
27	///
28	/// #[async_trait]
29	/// impl Session for MemorySession {
30	///     async fn append(
31	///         &self,
32	///         _events: &[SessionEvent],
33	///     ) -> Result<(), SessionError> {
34	///         Ok(())
35	///     }
36	///
37	///     async fn events(
38	///         &self,
39	///         _since: Option<SequenceId>,
40	///     ) -> Result<Vec<SessionEvent>, SessionError> {
41	///         Ok(Vec::new())
42	///     }
43	///
44	///     async fn snapshot(&self) -> Result<ConversationSnapshot, SessionError> {
45	///         Ok(ConversationSnapshot::default())
46	///     }
47	/// }
48	/// ```
49	#[async_trait]
50	pub trait Session: Send + Sync {
51	    /// Append events to the log.
52	    async fn append(&self, events: &[SessionEvent]) -> Result<(), SessionError>;
53	
54	    /// Read events from the log, optionally only those after `since`.
55	    async fn events(&self, since: Option<SequenceId>) -> Result<Vec<SessionEvent>, SessionError>;
56	
57	    /// Compute (or read) a [`ConversationSnapshot`] projection of the log.
58	    async fn snapshot(&self) -> Result<ConversationSnapshot, SessionError>;
59	}
60	
61	/// One entry in the conversation event log.
62	///
63	/// `UserMessage` / `AssistantMessage` / `ToolReturned` carry
64	/// `Vec<ContentPart>` directly (not `Item`) because the SessionEvent
65	/// variant *is* the role — wrapping `Item::UserMessage` inside
66	/// `SessionEvent::UserMessage` would double-tag.
67	#[derive(Debug, Clone, Serialize, Deserialize)]
68	#[serde(tag = "type", rename_all = "snake_case")]
69	#[non_exhaustive]
70	pub enum SessionEvent {
71	    /// A user-authored message.
72	    ///
73	    /// The enum is marked `#[non_exhaustive]` at the enum level (not per
74	    /// variant) so downstream tests and fixtures can construct variants
75	    /// by struct-init to pin a deterministic `ts`. Don't tighten this to
76	    /// per-variant `#[non_exhaustive]`.
77	    UserMessage {
78	        /// Content blocks of the message.
79	        content: Vec<ContentPart>,
80	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
81	        ts: Timestamp,
82	    },
83	    /// An assistant-authored message attributed to a named agent.
84	    AssistantMessage {
85	        /// Content blocks of the message.
86	        content: Vec<ContentPart>,
87	        /// Name of the emitting [`crate::Agent`]. `String` (not `Option`)
88	        /// because the runner always knows which agent emitted when
89	        /// appending to the log.
90	        agent: String,
91	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
92	        ts: Timestamp,
93	    },
94	    /// The runner invoked a tool.
95	    ToolCalled {
96	        /// Provider-assigned call identifier.
97	        call_id: String,
98	        /// Tool name.
99	        name: String,
100	        /// JSON arguments.
101	        args: serde_json::Value,
102	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
103	        ts: Timestamp,
104	    },
105	    /// The tool returned.
106	    ToolReturned {
107	        /// Matching call identifier.
108	        call_id: String,
109	        /// Content blocks of the tool's output (Anthropic permits
110	        /// text + image inside a tool result).
111	        content: Vec<ContentPart>,
112	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
113	        ts: Timestamp,
114	    },
115	    /// Control transferred from one agent to another.
116	    HandoffOccurred {
117	        /// Outgoing agent name.
118	        from: String,
119	        /// Incoming agent name.
120	        to: String,
121	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
122	        ts: Timestamp,
123	    },
124	    /// Older events were compacted into a summary.
125	    ///
126	    /// **Provider-translator caveat:** [`project`] renders this as
127	    /// [`Item::System`]. Both shipped provider translators reshape
128	    /// `Item::System`: Anthropic hoists every system block into the
129	    /// top-level `system` field, and OpenAI concatenates multiple system
130	    /// blocks into one at the top of the conversation. The "summary
131	    /// replaces turns 1..N at this position" semantic is therefore
132	    /// observation-only in the event log; the model sees the summary text
133	    /// but as a top-level system instruction, not a positional cutover.
134	    Compacted {
135	        /// LLM-produced summary.
136	        summary: String,
137	        /// Number of events the summary replaces. `u64` (not `usize`)
138	        /// because the value is serialized into the persisted log — a
139	        /// 32-bit consumer must read what a 64-bit producer wrote.
140	        original_count: u64,
141	        /// Wall-clock instant the event was recorded. UTC, nanosecond precision.
142	        ts: Timestamp,
143	    },
144	}
145	
146	impl SessionEvent {
147	    /// Construct a [`SessionEvent::UserMessage`] with `ts = Timestamp::now()`.
148	    pub fn user_message(content: Vec<ContentPart>) -> Self {
149	        Self::UserMessage {
150	            content,
151	            ts: Timestamp::now(),
152	        }
153	    }
154	
155	    /// Construct a [`SessionEvent::AssistantMessage`] with `ts = Timestamp::now()`.
156	    pub fn assistant_message(content: Vec<ContentPart>, agent: impl Into<String>) -> Self {
157	        Self::AssistantMessage {
158	            content,
159	            agent: agent.into(),
160	            ts: Timestamp::now(),
161	        }
162	    }
163	
164	    /// Construct a [`SessionEvent::ToolCalled`] with `ts = Timestamp::now()`.
165	    pub fn tool_called(
166	        call_id: impl Into<String>,
167	        name: impl Into<String>,
168	        args: serde_json::Value,
169	    ) -> Self {
170	        Self::ToolCalled {
171	            call_id: call_id.into(),
172	            name: name.into(),
173	            args,
174	            ts: Timestamp::now(),
175	        }
176	    }
177	
178	    /// Construct a [`SessionEvent::ToolReturned`] with `ts = Timestamp::now()`.
179	    pub fn tool_returned(call_id: impl Into<String>, content: Vec<ContentPart>) -> Self {
180	        Self::ToolReturned {
181	            call_id: call_id.into(),
182	            content,
183	            ts: Timestamp::now(),
184	        }
185	    }
186	
187	    /// Construct a [`SessionEvent::HandoffOccurred`] with `ts = Timestamp::now()`.
188	    pub fn handoff_occurred(from: impl Into<String>, to: impl Into<String>) -> Self {
189	        Self::HandoffOccurred {
190	            from: from.into(),
191	            to: to.into(),
192	            ts: Timestamp::now(),
193	        }
194	    }
195	
196	    /// Construct a [`SessionEvent::Compacted`] with `ts = Timestamp::now()`.
197	    pub fn compacted(summary: impl Into<String>, original_count: u64) -> Self {
198	        Self::Compacted {
199	            summary: summary.into(),
200	            original_count,
201	            ts: Timestamp::now(),
202	        }
203	    }
204	
205	    /// The serde tag for this variant (`"user_message"`, `"compacted"`, …).
206	    /// Matches the `type` field written to the persisted log.
207	    pub fn kind(&self) -> &'static str {
208	        // No `_ =>` arm: a new #[non_exhaustive] variant must fail to compile
209	        // here, in core, rather than silently mis-tagging in a backend.
210	        match self {
211	            SessionEvent::UserMessage { .. } => "user_message",
212	            SessionEvent::AssistantMessage { .. } => "assistant_message",
213	            SessionEvent::ToolCalled { .. } => "tool_called",
214	            SessionEvent::ToolReturned { .. } => "tool_returned",
215	            SessionEvent::HandoffOccurred { .. } => "handoff_occurred",
216	            SessionEvent::Compacted { .. } => "compacted",
217	        }
218	    }
219	
220	    /// The wall-clock instant this event was recorded.
221	    pub fn ts(&self) -> Timestamp {
222	        match self {
223	            SessionEvent::UserMessage { ts, .. }
224	            | SessionEvent::AssistantMessage { ts, .. }
225	            | SessionEvent::ToolCalled { ts, .. }
226	            | SessionEvent::ToolReturned { ts, .. }
227	            | SessionEvent::HandoffOccurred { ts, .. }
228	            | SessionEvent::Compacted { ts, .. } => *ts,
229	        }
230	    }
231	
232	    /// [`Self::ts`] as `i64` nanoseconds since the Unix epoch, saturating to
233	    /// `i64::MIN`/`i64::MAX` outside ±292 years from 1970. For denormalized
234	    /// audit-index columns; the canonical timestamp lives in the JSON payload.
235	    pub fn ts_nanos_saturating(&self) -> i64 {
236	        let nanos_i128 = self.ts().as_nanosecond();
237	        let saturated = if nanos_i128 < 0 { i64::MIN } else { i64::MAX };
238	        i64::try_from(nanos_i128).unwrap_or(saturated)
239	    }
240	}
241	
242	/// In-memory [`Session`] backend backed by a `std::sync::Mutex<Vec<_>>`.
243	///
244	/// Suitable for tests and ephemeral runs. One instance is one session by
245	/// construction — there is no `session_id`. For persistent or multi-session
246	/// storage, see `paigasus-helikon-sessions-sqlite`.
247	///
248	/// Lock poisoning panics (`expect`): if a panic occurred inside a critical
249	/// section, an invariant is already broken. Fail loud.
250	///
251	/// **Platform assumption:** [`MemorySession::events`] panics on 32-bit
252	/// targets if a single session accumulates more than `u32::MAX` events
253	/// (the `SequenceId` → `usize` conversion via [`usize::try_from`] then
254	/// fails). Sessions of that size are unreachable in practice; the panic
255	/// is intentional rather than a typed `SessionError` so the failure
256	/// surfaces immediately rather than being silently treated as a backend
257	/// error.
258	#[derive(Debug, Default)]
259	pub struct MemorySession {
260	    inner: std::sync::Mutex<Vec<SessionEvent>>,
261	}
262	
263	impl MemorySession {
264	    /// Create an empty [`MemorySession`].
265	    pub fn new() -> Self {
266	        Self::default()
267	    }
268	}
269	
270	#[async_trait]
271	impl Session for MemorySession {
272	    async fn append(&self, events: &[SessionEvent]) -> Result<(), SessionError> {
273	        let mut guard = self.inner.lock().expect("MemorySession mutex poisoned");
274	        guard.extend_from_slice(events);
275	        Ok(())
276	    }
277	
278	    async fn events(&self, since: Option<SequenceId>) -> Result<Vec<SessionEvent>, SessionError> {
279	        let guard = self.inner.lock().expect("MemorySession mutex poisoned");
280	        // `since` is *exclusive* — matches the existing trait doc ("those
281	        // after `since`"). `try_from` ensures 32-bit targets fail loudly
282	        // instead of wrapping past `u32::MAX`; `saturating_add` then guards
283	        // the +1 against the SequenceId(u64::MAX) edge case on 64-bit where
284	        // usize::MAX + 1 would overflow. Both branches are unreachable in
285	        // practice; the saturated result clamps `start` so the slice below
286	        // returns an empty Vec rather than wrapping.
287	        let start = match since {
288	            Some(s) => usize::try_from(s.0)
289	                .expect("SequenceId exceeds platform usize")
290	                .saturating_add(1),
291	            None => 0,
292	        };
293	        Ok(guard.get(start..).unwrap_or(&[]).to_vec())
294	    }
295	
296	    async fn snapshot(&self) -> Result<ConversationSnapshot, SessionError> {
297	        let events = self.events(None).await?;
298	        Ok(project(&events))
299	    }
300	}
301	
302	/// Project an append-only [`SessionEvent`] log into a [`ConversationSnapshot`]
303	/// — the canonical message-list view that providers consume.
304	///
305	/// **Provider-translator caveat:** `Compacted` events render as
306	/// [`Item::System`]. Both shipped provider translators (SMA-316 OpenAI,
307	/// SMA-317 Anthropic) reshape system messages — Anthropic hoists every
308	/// `Item::System` into the top-level `system` field; OpenAI concatenates
309	/// multiple system blocks into one at the top of the conversation. The
310	/// "summary replaces turns 1..N at this position" semantic is therefore
311	/// observation-only in the event log; the model sees the summary text but
312	/// as a top-level system instruction, not a positional cutover.
313	pub fn project(events: &[SessionEvent]) -> ConversationSnapshot {
314	    let mut messages: Vec<Item> = Vec::new();
315	    // Parallel vec: contributions[i] = number of messages event i produced.
316	    // Needed because Compacted has to undo the message yield of the previous
317	    // N events, and yield varies per variant (HandoffOccurred = 0, others = 1).
318	    let mut contributions: Vec<usize> = Vec::new();
319	
320	    for ev in events {
321	        match ev {
322	            SessionEvent::UserMessage { content, .. } => {
323	                messages.push(Item::UserMessage {
324	                    content: content.clone(),
325	                });
326	                contributions.push(1);
327	            }
328	            SessionEvent::AssistantMessage { content, agent, .. } => {
329	                messages.push(Item::AssistantMessage {
330	                    content: content.clone(),
331	                    agent: Some(agent.clone()),
332	                });
333	                contributions.push(1);
334	            }
335	            SessionEvent::ToolCalled {
336	                call_id,
337	                name,
338	                args,
339	                ..
340	            } => {
341	                messages.push(Item::ToolCall {
342	                    call_id: call_id.clone(),
343	                    name: name.clone(),
344	                    args: args.clone(),
345	                });
346	                contributions.push(1);
347	            }
348	            SessionEvent::ToolReturned {
349	                call_id, content, ..
350	            } => {
351	                messages.push(Item::ToolResult {
352	                    call_id: call_id.clone(),
353	                    content: content.clone(),
354	                });
355	                contributions.push(1);
356	            }
357	            SessionEvent::HandoffOccurred { .. } => {
358	                // Audit-only event; no message produced.
359	                contributions.push(0);
360	            }
361	            SessionEvent::Compacted {
362	                summary,
363	                original_count,
364	                ..
365	            } => {
366	                let n = usize::try_from(*original_count).unwrap_or(usize::MAX);
367	                if n == 0 {
368	                    tracing::warn!(
369	                        target: "paigasus::core::session",
370	                        "Compacted event with original_count = 0; emitting summary as a system message without compacting any history (likely producer bug — use SessionEvent::compacted with a positive count)"
371	                    );
372	                }
373	                if n > contributions.len() {
374	                    tracing::warn!(
375	                        target: "paigasus::core::session",
376	                        original_count = n,
377	                        events_seen = contributions.len(),
378	                        "Compacted event references more events than have been seen; treating as 'compact everything observed so far' (likely corrupt log)"
379	                    );
380	                }
381	                let drop_from_idx = contributions.len().saturating_sub(n);
382	                let drop_msg_count: usize = contributions[drop_from_idx..].iter().sum();
383	                let new_len = messages.len() - drop_msg_count;
384	                messages.truncate(new_len);
385	                // Drop the contribution entries the Compacted event subsumed
386	                // so a subsequent Compacted's `n` indexes back over the
387	                // remaining events, not the already-summarized ones.
388	                contributions.truncate(drop_from_idx);
389	                messages.push(Item::System {
390	                    content: vec![ContentPart::Text {
391	                        text: summary.clone(),
392	                    }],
393	                });
394	                contributions.push(1);
395	            }
396	        }
397	    }
398	
399	    ConversationSnapshot { messages }
400	}
401	
402	/// Accumulates one run's semantic items as [`SessionEvent`]s for the runner to
403	/// persist at run exit.
404	///
405	/// The runner pre-seeds the recorder with the run's `AgentInput` messages (the
406	/// new turn — which the agent does not re-emit on its event stream), then feeds
407	/// it every [`crate::AgentEvent`] as the stream flows. [`SessionRecorder::drain`]
408	/// returns the accumulated log, synthesizing a [`SessionEvent::ToolReturned`]
409	/// for any tool call left without a result (a run interrupted mid-tool) so the
410	/// log always [`project`]s to a provider-valid conversation.
411	#[derive(Debug)]
412	pub struct SessionRecorder {
413	    events: Vec<SessionEvent>,
414	    current_agent: String,
415	}
416	
417	impl SessionRecorder {
418	    /// Create a recorder seeded with the root agent's name. Used to attribute
419	    /// assistant messages whose [`Item::AssistantMessage`] `agent` is `None`,
420	    /// before any `RunStarted`/`AgentUpdated` updates the tracked agent.
421	    pub fn new(root_agent: impl Into<String>) -> Self {
422	        Self {
423	            events: Vec::new(),
424	            current_agent: root_agent.into(),
425	        }
426	    }
427	
428	    /// Record the run's input messages (the new turn). The agent never re-emits
429	    /// these on its event stream, so the runner records them directly.
430	    /// [`Item::System`] has no [`SessionEvent`] equivalent and is skipped.
431	    pub fn record_input(&mut self, messages: &[Item]) {
432	        for item in messages {
433	            match item {
434	                Item::UserMessage { content } => {
435	                    self.events
436	                        .push(SessionEvent::user_message(content.clone()));
437	                }
438	                Item::AssistantMessage { content, agent } => {
439	                    let name = agent.clone().unwrap_or_else(|| self.current_agent.clone());
440	                    self.events
441	                        .push(SessionEvent::assistant_message(content.clone(), name));
442	                }
443	                Item::ToolCall {
444	                    call_id,
445	                    name,
446	                    args,
447	                } => {
448	                    self.events.push(SessionEvent::tool_called(
449	                        call_id.clone(),
450	                        name.clone(),
451	                        args.clone(),
452	                    ));
453	                }
454	                Item::ToolResult { call_id, content } => {
455	                    self.events.push(SessionEvent::tool_returned(
456	                        call_id.clone(),
457	                        content.clone(),
458	                    ));
459	                }
460	                Item::System { .. } => {
461	                    tracing::debug!(
462	                        target: "paigasus::core::session",
463	                        "SessionRecorder: skipping Item::System in input (no SessionEvent variant)"
464	                    );
465	                }
466	            }
467	        }
468	    }
469	
470	    /// Observe one [`crate::AgentEvent`] from the run's stream: record the
471	    /// semantic items (assistant messages, tool calls, tool results, handoffs)
472	    /// and track the active agent from `RunStarted` / `AgentUpdated`.
473	    pub fn observe(&mut self, event: &AgentEvent) {
474	        match event {
475	            AgentEvent::RunStarted { agent } | AgentEvent::AgentUpdated { agent } => {
476	                self.current_agent = agent.clone();
477	            }
478	            AgentEvent::MessageOutput {
479	                item: Item::AssistantMessage { content, agent },
480	            } => {
481	                let name = agent.clone().unwrap_or_else(|| self.current_agent.clone());
482	                self.events
483	                    .push(SessionEvent::assistant_message(content.clone(), name));
484	            }
485	            AgentEvent::ToolCallItem {
486	                item:
487	                    Item::ToolCall {
488	                        call_id,
489	                        name,
490	                        args,
491	                    },
492	            } => {
493	                self.events.push(SessionEvent::tool_called(
494	                    call_id.clone(),
495	                    name.clone(),
496	                    args.clone(),
497	                ));
498	            }
499	            AgentEvent::ToolOutputItem {
500	                item: Item::ToolResult { call_id, content },
501	            } => {
502	                self.events.push(SessionEvent::tool_returned(
503	                    call_id.clone(),
504	                    content.clone(),
505	                ));
506	            }
507	            AgentEvent::HandoffItem { from, to } => {
508	                self.events
509	                    .push(SessionEvent::handoff_occurred(from.clone(), to.clone()));
510	            }
511	            _ => {}
512	        }
513	    }
514	
515	    /// Drain the accumulated events, appending a synthesized
516	    /// [`SessionEvent::ToolReturned`] for every [`SessionEvent::ToolCalled`]
517	    /// left without a matching result (a run cancelled/timed out mid-tool).
518	    /// The returned log always [`project`]s to a provider-valid conversation.
519	    pub fn drain(&mut self) -> Vec<SessionEvent> {
520	        let returned: std::collections::HashSet<String> = self
521	            .events
522	            .iter()
523	            .filter_map(|e| match e {
524	                SessionEvent::ToolReturned { call_id, .. } => Some(call_id.clone()),
525	                _ => None,
526	            })
527	            .collect();
528	        let mut synthesized = Vec::new();
529	        for e in &self.events {
530	            if let SessionEvent::ToolCalled { call_id, .. } = e {
531	                if !returned.contains(call_id) {
532	                    synthesized.push(SessionEvent::tool_returned(
533	                        call_id.clone(),
534	                        vec![ContentPart::Text {
535	                            text: "tool call did not complete (run cancelled/timed out)".to_owned(),
536	                        }],
537	                    ));
538	                }
539	            }
540	        }
541	        let mut out = std::mem::take(&mut self.events);
542	        out.extend(synthesized);
543	        out
544	    }
545	}
546	
547	/// Monotonic position in a [`Session`]'s append-only log.
548	#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
549	pub struct SequenceId(pub u64);
550	
551	/// A computed projection of a [`Session`]'s log into a single
552	/// conversation state. The `messages` field is the canonical view a
553	/// session emits.
554	#[derive(Debug, Clone, Default, Serialize, Deserialize)]
555	#[non_exhaustive]
556	pub struct ConversationSnapshot {
557	    /// Canonical message list, in conversational order.
558	    pub messages: Vec<Item>,
559	}
560	
561	/// Errors raised by [`Session`] methods.
562	#[derive(Debug, thiserror::Error)]
563	#[non_exhaustive]
564	pub enum SessionError {
565	    /// Backend unreachable (database down, file locked, …).
566	    #[error("session backend unavailable")]
567	    Unavailable,
568	
569	    /// A backend-specific error, type-erased so core stays free of any
570	    /// particular backend dependency. The `'static` bound is required for
571	    /// `<dyn Error>::downcast_ref` to work; callers who care about
572	    /// the underlying type can do `err.downcast_ref::<sqlx::Error>()`.
573	    #[error(transparent)]
574	    Backend(Box<dyn std::error::Error + Send + Sync + 'static>),
575	
576	    /// Escape hatch.
577	    #[error(transparent)]
578	    Other(#[from] anyhow::Error),
579	}
580	
581	impl SessionError {
582	    /// Wrap a backend-specific error as [`SessionError::Backend`].
583	    ///
584	    /// Saves the
585	    /// `.map_err(|e| SessionError::Backend(Box::new(e)))` boilerplate at
586	    /// every query call site — use as `.map_err(SessionError::backend)`.
587	    pub fn backend<E>(e: E) -> Self
588	    where
589	        E: std::error::Error + Send + Sync + 'static,
590	    {
591	        Self::Backend(Box::new(e))
592	    }
593	}
594	
595	#[cfg(test)]
596	mod recorder_tests {
597	    use super::*;
598	    use crate::AgentEvent;
599	
600	    fn text(s: &str) -> Vec<ContentPart> {
601	        vec![ContentPart::Text { text: s.to_owned() }]
602	    }
603	
604	    #[test]
605	    fn record_input_maps_user_and_skips_system() {
606	        let mut r = SessionRecorder::new("root");
607	        r.record_input(&[
608	            Item::System {
609	                content: text("sys"),
610	            },
611	            Item::UserMessage {
612	                content: text("hi"),
613	            },
614	        ]);
615	        let out = r.drain();
616	        assert_eq!(
617	            out.len(),
618	            1,
619	            "System is skipped; only the user message remains"
620	        );

