1	//! Handoff carrier types.
2	//!
3	//! A [`Handoff`] is a candidate agent an [`crate::LlmAgent`] may transfer the
4	//! conversation to. When the agent's `handoffs` list is non-empty, the loop
5	//! injects a synthetic `transfer_to_<slug>` tool per handoff; a model call to
6	//! one switches the active agent (see the agent-loop driver).
7	
8	use std::sync::Arc;
9	
10	use crate::Agent;
11	
12	/// A candidate agent the conversation may be transferred to.
13	///
14	/// Constructed via [`Handoff::to`] (owned agent) or [`Handoff::shared`]
15	/// (pre-wrapped trait object). This is intentionally a thin wrapper around
16	/// `Arc<dyn Agent<Ctx>>`; it is the named home for future per-edge config
17	/// (tool-name override, transcript input-filter).
18	pub struct Handoff<Ctx> {
19	    agent: Arc<dyn Agent<Ctx>>,
20	}
21	
22	impl<Ctx> Clone for Handoff<Ctx> {
23	    fn clone(&self) -> Self {
24	        Self {
25	            agent: Arc::clone(&self.agent),
26	        }
27	    }
28	}
29	
30	impl<Ctx> Handoff<Ctx>
31	where
32	    Ctx: Send + Sync + 'static,
33	{
34	    /// Transfer target from an owned agent (wrapped in `Arc`).
35	    pub fn to(agent: impl Agent<Ctx> + 'static) -> Self {
36	        Self {
37	            agent: Arc::new(agent),
38	        }
39	    }
40	
41	    /// Transfer target from a pre-wrapped trait object.
42	    pub fn shared(agent: Arc<dyn Agent<Ctx>>) -> Self {
43	        Self { agent }
44	    }
45	
46	    /// The target agent.
47	    pub fn agent(&self) -> &Arc<dyn Agent<Ctx>> {
48	        &self.agent
49	    }
50	
51	    /// Project the pure-data [`HandoffDef`] the state machine consumes.
52	    pub fn to_def(&self) -> HandoffDef {
53	        HandoffDef {
54	            tool_name: format!("transfer_to_{}", slug(self.agent.name())),
55	            target: self.agent.name().to_owned(),
56	            description: self.agent.description().to_owned(),
57	        }
58	    }
59	}
