61	/// Pure-data description of one injected `transfer_to_*` tool.
62	///
63	/// Built by the agent-loop driver from each [`Handoff`] before the run, and
64	/// passed into [`crate::TransitionCtx`] so the pure state machine can both
65	/// advertise the transfer tools and recognize a call to one.
66	#[derive(Debug, Clone)]
67	pub struct HandoffDef {
68	    /// The synthetic tool name the model sees, `transfer_to_<slug>`.
69	    pub tool_name: String,
70	    /// The **real** target agent name (used in events and target lookup).
71	    pub target: String,
72	    /// The target agent's description (shown to the model).
73	    pub description: String,
74	}
75	
76	/// Lowercase `name`, collapsing every run of non-ASCII-alphanumeric characters
77	/// to a single `_`, with leading/trailing `_` trimmed. `"Investing specialist"`
78	/// → `"investing_specialist"`. Non-ASCII characters (accents, CJK, …) are
79	/// treated as non-alphanumeric and collapsed, so an all-non-ASCII name slugs to
80	/// the empty string (yielding `transfer_to_`); the driver's collision check
81	/// still rejects two such names loudly rather than silently mis-routing.
82	fn slug(name: &str) -> String {
83	    let mut out = String::with_capacity(name.len());
84	    let mut prev_underscore = false;
85	    for ch in name.chars() {
86	        if ch.is_ascii_alphanumeric() {
87	            out.push(ch.to_ascii_lowercase());
88	            prev_underscore = false;
89	        } else if !prev_underscore {
90	            out.push('_');
91	            prev_underscore = true;
92	        }
93	    }
94	    out.trim_matches('_').to_owned()
95	}
