456	impl TokenUsage {
457	    /// Add another usage record (per-turn aggregation across a run).
458	    ///
459	    /// `total_tokens` is summed alongside the other fields rather than
460	    /// recomputed from them, preserving each turn's provider-reported total.
461	    pub fn add(&mut self, other: TokenUsage) {
462	        self.input_tokens += other.input_tokens;
463	        self.output_tokens += other.output_tokens;
464	        self.cached_input_tokens += other.cached_input_tokens;
465	        self.reasoning_tokens += other.reasoning_tokens;
466	        self.total_tokens += other.total_tokens;
467	    }
468	}
