495	/// Why a runner's control boundary aborted a run before its natural end.
496	///
497	/// A runner that wraps the agent's event stream with cancellation and/or a
498	/// deadline observes at most one of these. Whether it actually *wins* — that
499	/// is, overrides the run's own outcome — is decided by [`effective_interrupt`],
500	/// never by the runner on its own.
501	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
502	#[non_exhaustive]
503	pub enum RunInterrupt {
504	    /// The run's [`crate::CancellationToken`] fired.
505	    Cancelled,
506	    /// The run exceeded its [`RunConfig::timeout`].
507	    TimedOut,
508	}
509	
510	impl RunInterrupt {
511	    /// The [`RunError`] this interrupt surfaces at the runner boundary.
512	    #[must_use]
513	    pub fn run_error(self) -> RunError {
514	        // No wildcard arm: `#[non_exhaustive]` does not apply inside the
515	        // defining crate, so a new variant breaks this match at compile time —
516	        // which is the point.
517	        match self {
518	            Self::Cancelled => RunError::Cancelled,
519	            Self::TimedOut => RunError::Timeout,
520	        }
521	    }
522	
523	    /// Canonical `error` text for the terminal [`crate::AgentEvent::RunFailed`]
524	    /// a streaming runner synthesizes when this interrupt wins.
525	    ///
526	    /// This is the text alone. Use [`RunInterrupt::terminal_event`] when you
527	    /// need the whole frame — a runner should not assemble one by hand.
528	    #[must_use]
529	    pub fn terminal_message(self) -> &'static str {
530	        match self {
531	            Self::Cancelled => "run cancelled",
532	            Self::TimedOut => "run timed out",
533	        }
534	    }
535	
536	    /// The terminal [`AgentEvent`] a streaming runner yields when this interrupt
537	    /// wins — see [`effective_interrupt`].
538	    ///
539	    /// Renders through [`RunInterrupt::terminal_message`], so a runner never
540	    /// assembles the frame itself and every runner emits identical bytes for the
541	    /// same interrupt. There is deliberately no second `match self` here: one
542	    /// wildcard-free match per rendering is what makes the `#[non_exhaustive]`
543	    /// compile-break guard worth anything.
544	    #[must_use]
545	    pub fn terminal_event(self) -> AgentEvent {
546	        AgentEvent::RunFailed {
547	            error: self.terminal_message().to_owned(),
548	        }
549	    }
550	}
551	
552	/// Delegates to [`RunInterrupt::run_error`], which stays the canonical,
553	/// documented name for this mapping.
554	///
555	/// The `.into()` form is for runner implementations reporting an interrupt that
556	/// won at the control boundary:
557	///
558	/// ```
559	/// use paigasus_helikon_core::{effective_interrupt, RunError, RunInterrupt};
560	///
561	/// fn report(interrupt: Option<RunInterrupt>, saw_terminal: bool) -> Result<(), RunError> {
562	///     if let Some(i) = effective_interrupt(interrupt, saw_terminal) {
563	///         return Err(i.into());
564	///     }
565	///     Ok(())
566	/// }
567	///
568	/// // The interrupt aborted the run in-flight: it wins and converts.
569	/// assert!(matches!(
570	///     report(Some(RunInterrupt::TimedOut), false),
571	///     Err(RunError::Timeout)
572	/// ));
573	/// // A genuine terminal already occurred: the interrupt loses.
574	/// assert!(report(Some(RunInterrupt::TimedOut), true).is_ok());
575	/// ```
576	impl From<RunInterrupt> for RunError {
577	    fn from(interrupt: RunInterrupt) -> Self {
578	        interrupt.run_error()
579	    }
580	}
581	
582	/// Apply the runner-boundary precedence rule: **a genuine terminal event beats
583	/// a late cancel/timeout.**
584	///
585	/// `interrupt` is what the runner's control boundary observed (`None` if it
586	/// never fired). `saw_terminal` is whether the run produced a genuine
587	/// terminal event — see [`crate::AgentEvent::is_terminal`]. Returns the
588	/// interrupt only when it *wins*: when it aborted the run in-flight, before any
589	/// terminal.
590	///
591	/// This is the executable form of the contract [`Runner::run`] states in prose.
592	/// It exists so that every `Runner` — third-party implementations especially,
593	/// which are its main audience — applies one shared rule instead of re-deriving
594	/// it. The window it closes: a cancel that fires *after* the terminal already
595	/// went out (during a suspending `OnRunComplete` hook, say) must not
596	/// retroactively turn a completed run into a cancelled one.
597	///
598	/// ```
599	/// use paigasus_helikon_core::{effective_interrupt, RunInterrupt};
600	///
601	/// // Aborted in-flight: the interrupt wins.
602	/// assert_eq!(
603	///     effective_interrupt(Some(RunInterrupt::Cancelled), false),
604	///     Some(RunInterrupt::Cancelled)
605	/// );
606	/// // A terminal already occurred: the interrupt loses.
607	/// assert_eq!(effective_interrupt(Some(RunInterrupt::Cancelled), true), None);
608	/// ```
609	#[must_use]
610	pub fn effective_interrupt(
611	    interrupt: Option<RunInterrupt>,
612	    saw_terminal: bool,
613	) -> Option<RunInterrupt> {
614	    if saw_terminal {
615	        None
616	    } else {
617	        interrupt
618	    }
619	}
