    async fn call_tool(
        &self,
        request: CallToolRequestParams,
        context: RequestContext<RoleServer>,
    ) -> Result<CallToolResponse, ErrorData> {
        if request.name != self.tool_name {
            return Err(ErrorData::invalid_params(
                format!("unknown tool: {}", request.name),
                None,
            ));
        }
        let args = request.arguments.as_ref();
        let input_val = args.and_then(|a| a.get("input")).ok_or_else(|| {
            ErrorData::invalid_params("missing required argument `input`".to_owned(), None)
        })?;
        let input = input_val
            .as_str()
            .ok_or_else(|| {
                ErrorData::invalid_params("argument `input` must be a string".to_owned(), None)
            })?
            .to_owned();

        // The run's token is a child of rmcp's per-request token, so a client
        // disconnect or `notifications/cancelled` cancels the agent run.
        let cancel = context.ct.child_token();
        let run_ctx = RunContext::new(
            Arc::new((self.ctx_factory)()),
            Arc::new(MemorySession::new()) as Arc<dyn Session>,
            HookRegistry::new(),
            TracerHandle::builder().build(),
            cancel.clone(),
        )
        .with_run_config(self.run_config.clone());

        let agent = Arc::clone(&self.agent);
        let run = async move {
            let stream = agent
                .run(run_ctx, AgentInput::from_user_text(input))
                .await
                .map_err(|e| e.to_string())?;
            // Deliberate divergence from TokioRunner: no with_failure() slot — at this
            // boundary every failure is stringified into CallToolResult::error anyway,
            // so the opaque RunFailed string suffices. Wire the failure handle if
            // structured error mapping is ever needed here.
            RunResultStreaming::new(stream)
                .collect()
                .await
                .map_err(|e| e.to_string())
        };

        // Core has no timer; RunConfig::timeout is enforced at this boundary.
        let outcome = match self.run_config.timeout {
            Some(deadline) => match tokio::time::timeout(deadline, run).await {
                Ok(outcome) => outcome,
                Err(_elapsed) => {
                    cancel.cancel();
                    return Ok(CallToolResponse::Complete(CallToolResult::error(vec![
                        ContentBlock::text("agent run timed out"),
                    ])));
                }
            },
            None => run.await,
        };

        // rmcp 3 widened `call_tool`'s return to `CallToolResponse`, whose other
        // variants (`InputRequired`, `Task`) let a server defer completion. This
        // handler always runs the agent to completion inline, so every path is
        // `Complete` — the same value the rmcp 2 signature returned directly.
        match outcome {
            Ok(result) => Ok(CallToolResponse::Complete(CallToolResult::success(vec![
                ContentBlock::text(result.final_output),
            ]))),
            Err(e) => Ok(CallToolResponse::Complete(CallToolResult::error(vec![
                ContentBlock::text(format!("agent run failed: {e}")),
            ]))),
        }
    }
}

