1	//! The public per-tool-call execution pipeline: resolve → authorize →
2	//! invoke → redact → convert.
3	//!
4	//! This is the primitive a durable runner (e.g. a Temporal activity) calls
5	//! directly to execute one tool call with exactly the same authorization and
6	//! redaction the ephemeral `LlmAgent` loop applies inline — so a durable
7	//! runner never writes unauthorized or unredacted tool output into its
8	//! history. The ephemeral loop driver composes the same building blocks
9	//! ([`crate::RunContext::authorize_tool`] and [`finalize_tool_output`])
10	//! around its own hook interleave; [`execute_tool_call`] is the hook-free
11	//! version for callers with no hook registry to fire.
12	
13	/// Render a tool's raw JSON output to content parts, applying redaction last.
14	///
15	/// Redaction is deliberately the final transform: whatever a caller did to
16	/// the JSON beforehand (e.g. a `PostToolUse` hook rewriting it), this
17	/// function's redaction pass runs after, so nothing downstream can
18	/// reintroduce a secret past it.
19	pub fn finalize_tool_output(
20	    output: serde_json::Value,
21	    redact_output: bool,
22	    secrets: &crate::redaction::SecretSet,
23	) -> Vec<crate::ContentPart> {
24	    let output = if redact_output {
25	        crate::redaction::redact(&output, secrets)
26	    } else {
27	        output
28	    };
29	    tool_output_to_content_parts(&crate::ToolOutput::new(output))
30	}
31	
32	/// Conversion convention: `ToolOutput.content` (SMA-313's
33	/// `serde_json::Value`) becomes one `ContentPart::Text`.
34	/// `Value::String(s) -> ContentPart::Text { text: s }`; other JSON
35	/// values are stringified via `Value::to_string()`.
36	pub(crate) fn tool_output_to_content_parts(output: &crate::ToolOutput) -> Vec<crate::ContentPart> {
37	    let text = match &output.content {
38	        serde_json::Value::String(s) => s.clone(),
39	        v => v.to_string(),
40	    };
41	    vec![crate::ContentPart::Text { text }]
42	}
43	
44	/// The hook-free single-call pipeline durable runners execute:
45	/// resolve → authorize → invoke → redact → convert. Returns the outcome plus
46	/// an optional `AgentEvent::PermissionDenied` to surface.
47	///
48	/// Tool resolution mirrors the ephemeral loop driver: an unknown tool name
49	/// still runs the authorize step first (using [`crate::ToolEffect::SideEffect`]
50	/// as its effective side-effect profile), and only fails with `unknown tool:
51	/// {name}` once authorization allows the call through.
52	pub async fn execute_tool_call<Ctx>(
53	    tools: &[std::sync::Arc<dyn crate::Tool<Ctx>>],
54	    run_ctx: &crate::RunContext<Ctx>,
55	    tool_ctx: &crate::ToolContext<Ctx>,
56	    call: &crate::ToolCallRequest,
57	) -> (crate::ToolCallOutcome, Option<crate::AgentEvent>)
58	where
59	    Ctx: Send + Sync + 'static,
60	{
61	    let tool = tools.iter().find(|t| t.name() == call.name).cloned();
62	    let effect = tool
63	        .as_ref()
64	        .map(|t| t.effect())
65	        .unwrap_or(crate::ToolEffect::SideEffect);
66	
67	    let mut args = call.args.clone();
68	    match run_ctx.authorize_tool(&call.name, effect, &args).await {
69	        crate::PermissionDecision::Allow => {}
70	        crate::PermissionDecision::Replace { args: sanitized } => {
71	            args = sanitized;
72	        }
73	        crate::PermissionDecision::Deny { reason }
74	        | crate::PermissionDecision::AskUser { prompt: reason } => {
75	            let outcome = crate::ToolCallOutcome {
76	                call_id: call.call_id.clone(),
77	                result: Err(format!("permission denied: {reason}")),
78	            };
79	            let event = crate::AgentEvent::PermissionDenied {
80	                tool: call.name.clone(),
81	                reason,
82	            };
83	            return (outcome, Some(event));
84	        }
85	    }
86	
87	    let Some(tool) = tool else {
88	        return (
89	            crate::ToolCallOutcome {
90	                call_id: call.call_id.clone(),
91	                result: Err(format!("unknown tool: {}", call.name)),
92	            },
93	            None,
94	        );
95	    };
96	
97	    let result = match tool.invoke(tool_ctx, args).await {
98	        Ok(output) => {
99	            let secrets = crate::redaction::SecretSet::from_env_and_extra(run_ctx.extra_secrets());
100	            Ok(finalize_tool_output(
101	                output.content,
102	                run_ctx.redact_output(),
103	                &secrets,
104	            ))
105	        }
106	        Err(e) => Err(e.to_string()),
107	    };
108	
109	    (
110	        crate::ToolCallOutcome {
111	            call_id: call.call_id.clone(),
112	            result,
113	        },
114	        None,
115	    )
