1	//! [`AgentAsTool`] — expose any [`crate::Agent`] as a [`crate::Tool`].
2	//!
3	//! The parent agent calls the wrapped agent like any tool, gets its
4	//! `final_output` back as a [`crate::ToolOutput`], and keeps reasoning. The
5	//! sub-run is **isolated**: a fresh in-memory session and empty hooks, so its
6	//! internal turns never touch the parent's session log.
7	
8	use std::sync::Arc;
9	
10	use async_trait::async_trait;
11	use serde_json::Value;
12	
13	use crate::{
14	    Agent, AgentInput, HookRegistry, MemorySession, RunContext, RunError, RunResultStreaming, Tool,
15	    ToolContext, ToolError, ToolOutput,
16	};
17	
18	/// Adapter exposing an [`Agent`] as a [`Tool`].
19	///
20	/// The sub-run is **isolated**: a fresh in-memory session and empty hooks, so
21	/// its internal turns never touch the parent's session log. The wrapped agent
22	/// runs under its **own** [`crate::RunConfig`] — the parent's `run_config`
23	/// (`max_turns`, `timeout`, `max_agent_depth`) does **not** cross this boundary.
24	/// Only the nesting depth crosses: the parent-side guard caps entry at the
25	/// parent's `max_agent_depth`, and the wrapped agent's own config bounds any
26	/// further nesting it performs, so recursion stays bounded along the whole chain.
27	pub struct AgentAsTool<Ctx> {
28	    agent: Arc<dyn Agent<Ctx>>,
29	    name: String,
30	    description: String,
31	    schema: Value,
32	}
33	
34	impl<Ctx> AgentAsTool<Ctx>
35	where
36	    Ctx: Send + Sync + 'static,
37	{
38	    /// Wrap an owned agent. The tool name and description default to the
39	    /// agent's own; the argument schema is a single string field `input`.
40	    pub fn new(agent: impl Agent<Ctx> + 'static) -> Self {
41	        Self::shared(Arc::new(agent))
42	    }
43	
44	    /// Wrap a pre-wrapped agent.
45	    pub fn shared(agent: Arc<dyn Agent<Ctx>>) -> Self {
46	        let name = agent.name().to_owned();
47	        let description = agent.description().to_owned();
48	        Self {
49	            agent,
50	            name,
